('theory', 'kb_016', '{"tagId":"kb_016","originalNumber":16,"title":"呼び名効果","summary":"相手の名前や望む呼び方を適切に使うことで、注意や親近感を引き出しやすくなる実務的な考え方。過剰に繰り返すと不自然になる。","sourceType":"心理学","discipline":"社会心理学","conceptType":"効果・バイアス","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":"実務上の通称。学術的な正式名称・効果範囲を要確認。","categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 482),
('theory', 'kb_017', '{"tagId":"kb_017","originalNumber":17,"title":"カクテルパーティー効果","summary":"多くの音や情報の中でも、自分の名前や関心の高い情報には注意が向きやすい現象。人は自分に関係する情報を優先して拾う。","sourceType":"心理学","discipline":"社会心理学","conceptType":"効果・バイアス","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 483),
('theory', 'kb_018', '{"tagId":"kb_018","originalNumber":18,"title":"質問好意効果","summary":"相手に関心を持って質問し、話をよく聞く人は好意的に評価されやすい傾向。質問の量より、答えを受け止めて深めることが重要になる。","sourceType":"心理学","discipline":"社会心理学","conceptType":"効果・バイアス","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 484),
('theory', 'kb_019', '{"tagId":"kb_019","originalNumber":19,"title":"ベン・フランクリン効果","summary":"一度誰かを助けると、その行動と整合させるために相手への好意が高まりやすい傾向。小さな依頼が関係形成のきっかけになることがある。","sourceType":"心理学","discipline":"社会心理学","conceptType":"効果・バイアス","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 485),
('theory', 'kb_020', '{"tagId":"kb_020","originalNumber":20,"title":"自己検証理論","summary":"人は肯定的な評価だけでなく、自分が抱く自己像と一致する評価を求めるという理論。相手を理解するには、理想像だけでなく自己認識を見る必要がある。","sourceType":"心理学","discipline":"社会心理学","conceptType":"理論・モデル","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 486),
('theory', 'kb_021', '{"tagId":"kb_021","originalNumber":21,"title":"自己拡張理論","summary":"人は関係を通じて、新しい能力、視点、経験を自分の一部として取り込みたいと考えるという理論。成長を感じられる関係は魅力を持ちやすい。","sourceType":"心理学","discipline":"社会心理学","conceptType":"理論・モデル","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 487),
('theory', 'kb_022', '{"tagId":"kb_022","originalNumber":22,"title":"対人魅力の報酬理論","summary":"一緒にいることで快い感情や利益を得られる相手ほど、好意を持たれやすいという理論。相手にとっての心理的報酬が関係を支える。","sourceType":"心理学","discipline":"社会心理学","conceptType":"理論・モデル","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 488),
('theory', 'kb_023', '{"tagId":"kb_023","originalNumber":23,"title":"感情伝染","summary":"表情、声、態度を通じて、ある人の感情が周囲へ無意識に広がる現象。機嫌や不安は個人の内側だけで完結しない。","sourceType":"心理学","discipline":"社会心理学","conceptType":"概念・フレームワーク","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 489),
('theory', 'kb_024', '{"tagId":"kb_024","originalNumber":24,"title":"アクティブ・コンストラクティブ・レスポンディング","summary":"相手の良い報告に、関心と喜びを示しながら積極的に反応する方法。成功を一緒に喜ぶ反応は、単なる励まし以上に関係を強める。","sourceType":"心理学","discipline":"社会心理学","conceptType":"概念・フレームワーク","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 490),
('theory', 'kb_025', '{"tagId":"kb_025","originalNumber":25,"title":"プラットフォール効果","summary":"高い能力を持つ人が小さな失敗を見せると、親しみやすさが増すことがある現象。能力への信頼がない状態では、失敗はそのまま低評価になりうる。","sourceType":"心理学","discipline":"社会心理学","conceptType":"効果・バイアス","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 491),
('theory', 'kb_026', '{"tagId":"kb_026","originalNumber":26,"title":"ゲイン・ロス効果","summary":"一貫して好意的な評価より、否定的な評価から好意的な評価へ変化した方が強く好まれることがある現象。評価の変化幅が感情を強める。","sourceType":"心理学","discipline":"社会心理学","conceptType":"効果・バイアス","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 492),
('theory', 'kb_027', '{"tagId":"kb_027","originalNumber":27,"title":"誤帰属理論","summary":"ある原因で生じた感情や身体反応を、別の対象が原因だと誤って解釈することがあるという理論。","sourceType":"心理学","discipline":"社会心理学","conceptType":"理論・モデル","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 493),
('theory', 'kb_028', '{"tagId":"kb_028","originalNumber":28,"title":"吊り橋効果","summary":"恐怖や緊張による高揚を、目の前の相手への魅力だと誤認する可能性を示す現象。強い感情は、その原因を取り違えやすい。","sourceType":"心理学","discipline":"社会心理学","conceptType":"効果・バイアス","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 494),
('theory', 'kb_029', '{"tagId":"kb_029","originalNumber":29,"title":"ピーク・エンドの法則","summary":"体験全体は、最も感情が強かった瞬間と最後の印象によって記憶されやすいという法則。平均的な質だけでなく、山場と終わり方が重要になる。","sourceType":"心理学","discipline":"社会心理学","conceptType":"原理・法則","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 495),
('theory', 'kb_030', '{"tagId":"kb_030","originalNumber":30,"title":"社会的交換理論","summary":"人間関係を、得られる報酬と負担の比較から捉える理論。関係は感情だけでなく、互いの利益、コスト、代替可能性にも左右される。","sourceType":"心理学","discipline":"対人関係心理学","conceptType":"理論・モデル","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の管理"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 496),
('theory', 'kb_031', '{"tagId":"kb_031","originalNumber":31,"title":"衡平理論","summary":"人は、自分と相手の貢献と見返りの比率が釣り合っているときに公平だと感じるという理論。絶対量より、負担と利益のバランスが問題になる。","sourceType":"心理学","discipline":"対人関係心理学","conceptType":"理論・モデル","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の管理"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 497),
('theory', 'kb_032', '{"tagId":"kb_032","originalNumber":32,"title":"コミューナル関係・交換関係","summary":"相手の必要に応じて支え合う関係と、与えたものに相応の返礼を求める関係を区別する考え方。関係の前提を取り違えると不満が生まれる。","sourceType":"心理学","discipline":"対人関係心理学","conceptType":"概念・フレームワーク","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の管理"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 498),
('theory', 'kb_033', '{"tagId":"kb_033","originalNumber":33,"title":"相互依存性理論","summary":"自分の結果が相手の選択に、相手の結果が自分の選択に左右される関係を分析する理論。関係の力学は、依存度と代替選択肢によって変わる。","sourceType":"心理学","discipline":"対人関係心理学","conceptType":"理論・モデル","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の管理"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 499),
