('theory', 'kb_035', '{"tagId":"kb_035","originalNumber":35,"title":"最小関心原理","summary":"関係の継続をより強く望む側ほど、交渉上の力が弱くなりやすいという原理。離れる選択肢を持つ側が主導権を握りやすい。","sourceType":"心理学","discipline":"対人関係心理学","conceptType":"原理・法則","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の管理"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 501),
